import {
  PaletteProvider,
  useCommandPalette,
  usePaletteCommands,
} from "../../ui/command-palette/index.js";
import { SectionPage, Specimen } from "../kit.js";
import { toast } from "../../ui/toast/index.js";
import { Button } from "../../ui/button/index.js";

function DemoPaletteCommands() {
  const palette = useCommandPalette();
  usePaletteCommands([
    {
      id: "sample-open",
      label: "Open exhibition",
      group: "Projects",
      run: () => toast.info("Sample exhibition opened"),
    },
    {
      id: "sample-save",
      label: "Save exhibition",
      group: "Actions",
      run: () => toast.success("Sample saved"),
    },
  ]);
  return <Button onClick={palette.open}>Open command palette</Button>;
}

export default function PaletteProviderExample() {
  return (
    <SectionPage>
      <Specimen title="Register commands in a host" layout="stack">
        <PaletteProvider>
          <DemoPaletteCommands />
        </PaletteProvider>
      </Specimen>
    </SectionPage>
  );
}
